const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms));
const assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async bytes=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('');
const files=['app.js','engine.js','smart-sync.js','deck-tempo.js','gui-tempo-harness.js','fx-tempo-capture-worklet.js'];
async function identities(){const r={};for(const f of [...files,'tempo-slider.js']){const res=await fetch(f,{cache:'no-store'});r[f]=res.ok?await hash(await res.arrayBuffer()):'absent';}return r;}
async function until(fn,label){const deadline=performance.now()+15000;while(!fn()){assert(performance.now()<deadline,label+' timed out');await sleep(10);}}
function base64(bytes){let s='';for(let i=0;i<bytes.length;i+=16384)s+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(s);}
function metrics(data,sr){let energy=0,peak=0,finite=true;const crossings=[];for(let i=0;i<data.length;i++){const x=data[i];finite&&=Number.isFinite(x);energy+=x*x;peak=Math.max(peak,Math.abs(x));if(i&&data[i-1]<0&&x>=0)crossings.push(i-1-data[i-1]/(x-data[i-1]));}return{frames:data.length,finite,rms:Math.sqrt(energy/data.length),peak,hz:crossings.length>1?(crossings.length-1)*sr/(crossings.at(-1)-crossings[0]):null};}
let app,report,witnesses=[];
function output(){const text=JSON.stringify(report,null,2);$('#gui-tempo-original').textContent=text;$('#gui-tempo-results').textContent=JSON.stringify({...report,cases:report.cases.map(c=>({...c,pcm:c.pcm.map(p=>({...p,base64:'Retained in original'}))}))},null,2);}
async function prepare(){const{state,engine}=app;$('#gui-tempo-prepare').disabled=true;report={startedAt:new Date().toISOString(),scope:'Production app browser controls and actual generated-tone audio. Physical graph muted. Not native, physical MIDI, real music, exact vendor taper/GUI mapping, keylock/warp/StemSlip compositions or full parity.',sourceBefore:await identities(),criteria:{settleSeconds:.3,captureSeconds:.3,frequencyToleranceHz:.3,minimumRMS:.005,silencePeak:.000001},cases:[]};
 engine.init();engine.audioMonitor.mutePhysical(true);await engine.resume();assert(engine.audioMonitor.snapshot().physicalMuted,'Physical graph must be muted');await until(()=>!state.analysis,'Initial analysis');for(const d of state.decks)engine.pause(d);for(const bank of state.fx)for(const slot of bank)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],[120,100],state.fxTempo);
 await engine.ctx.audioWorklet.addModule(new URL('./fx-tempo-capture-worklet.js',import.meta.url));const split=engine.ctx.createChannelSplitter(2);engine.masterOutput.output.connect(split);for(let i=0;i<2;i++){const w=new AudioWorkletNode(engine.ctx,'open-play-fx-tempo-capture-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});split.connect(w,i);w.connect(engine.ctx.destination);witnesses.push(w);}report.sampleRate=engine.ctx.sampleRate;
 for(let i=0;i<2;i++){const d=state.decks[i],b=engine.ctx.createBuffer(2,engine.ctx.sampleRate*180,engine.ctx.sampleRate);for(let n=0;n<b.length;n++)b.getChannelData(i)[n]=.05*Math.sin(2*Math.PI*(i?550:330)*n/b.sampleRate);Object.assign(d.track,{bpm:i?100:120,grid:0,gridWarpMarkers:[],gridMarkers:[],duration:180,analyzed:true});Object.assign(d,{rate:1,position:0,pitchRange:8,keylock:false,keyShift:0,reverse:false,loop:false,sync:false,syncState:'off'});engine.clearDeckScratchCache(i);engine.buffers.set(d.track.id,b);engine.mix(i,'level',.8);}
 $('[data-panel="settings"]').click();$('[data-setting="Sync Mode"]').value='Smart Sync';$('[data-setting="Sync Mode"]').dispatchEvent(new Event('change',{bubbles:true}));$('#save-settings').click();
 for(let i=0;i<2;i++){$(`[data-deck="${i}"][data-action="sync"]`).click();$(`[data-deck="${i}"][data-action="play"]`).click();await until(()=>state.decks[i].playing&&!state.decks[i].processing,'Deck '+i+' playing');}
 await until(()=>Math.abs(state.decks[1].rate-1.2)<1e-8,'Synced20percent');await sleep(300);$('#gui-tempo-status').textContent='Prepared: two playing decks, deck2 +20% at ±8%; use actual GUI controls then Capture.';$('#gui-tempo-capture').disabled=false;$('#gui-tempo-finish').disabled=false;output();}
async function capture(){const{state,engine}=app;$('#gui-tempo-capture').disabled=true;await sleep(300);const c={at:new Date().toISOString(),rates:state.decks.slice(0,2).map(d=>d.rate),decks:state.decks.slice(0,2).map(d=>{const input=$(`[data-tempo="${d.index}"]`);return{sync:d.sync,state:d.syncState,playing:d.playing,pitchRange:d.pitchRange,position:engine.position(d),slider:{value:input.value,min:input.min,max:input.max,ariaValueText:input.getAttribute('aria-valuetext'),label:input.closest('label').textContent}};}),pcm:[],measured:[]};
 const id=report.cases.length+1,raw=await Promise.all(witnesses.map(w=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('PCM capture timeout')),5000);w.port.onmessage=({data})=>{if(data.type==='done'&&data.id===id){clearTimeout(timer);resolve(data);}};w.port.postMessage({type:'capture',id,frames:Math.round(engine.ctx.sampleRate*.3)});})));for(let i=0;i<2;i++){const bytes=new Uint8Array(raw[i].data.buffer);c.pcm.push({startFrame:raw[i].startFrame,frames:raw[i].data.length,sha256:await hash(bytes),base64:base64(bytes)});c.measured.push(metrics(raw[i].data,engine.ctx.sampleRate));}report.cases.push(c);output();$('#gui-tempo-status').textContent=`Captured ${report.cases.length}: rates ${c.rates.map(v=>v.toFixed(6)).join(' / ')}, frequencies ${c.measured.map(m=>m.hz?.toFixed(3)||'silent').join(' / ')}`;$('#gui-tempo-capture').disabled=false;}
async function finish(){for(const d of app.state.decks)app.engine.pause(d);await capture();for(const w of witnesses){w.disconnect();w.port.close();}report.sourceAfter=await identities();report.sourceStable=JSON.stringify(report.sourceBefore)===JSON.stringify(report.sourceAfter);report.finishedAt=new Date().toISOString();output();const link=$('#gui-tempo-download');link.href=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));link.download='gui-tempo-original.json';link.hidden=false;$('#gui-tempo-capture').disabled=true;$('#gui-tempo-finish').disabled=true;$('#gui-tempo-status').textContent='Stopped; original report ready.';}
for(const[id,fn]of[['prepare',prepare],['capture',capture],['finish',finish]])$('#gui-tempo-'+id).onclick=()=>fn().catch(e=>{$('#gui-tempo-status').textContent='Error: '+e.message;});
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[1].track,'Actual app');app=window.openPlay;$('#gui-tempo-prepare').disabled=false;$('#gui-tempo-status').textContent='Ready';}boot().catch(e=>$('#gui-tempo-status').textContent=e.message);
